from jsonb_to_recordset($json$[{"id":"che-st-201","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen combined with a non-metal is assigned the oxidation number","options":["$+1$","$-1$","$0$","$+2$"],"answer_index":0,"explanation":"In hydrides of non-metals (HCl, H$_2$O, NH$_3$) hydrogen is $+1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-202","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In their compounds the alkali metals (Li, Na, K, …) show the oxidation number","options":["$0$","$+1$","$+2$","$-1$"],"answer_index":1,"explanation":"Group 1 metals lose one valence electron and are $+1$ in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-203","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Fluorine, being the most electronegative element, has in all its compounds the oxidation number","options":["$0$","$+1$","$-1$","$+2$"],"answer_index":2,"explanation":"Fluorine is always $-1$ in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-204","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In hydrogen chloride the oxidation number of chlorine is","options":["$+1$","$-1$","$0$","$+7$"],"answer_index":1,"explanation":"H is $+1$ and the molecule is neutral, so Cl is $-1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-205","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sulphur in hydrogen sulphide $\\mathrm{H_2S}$ has the oxidation number","options":["$+2$","$-2$","$+6$","$0$"],"answer_index":1,"explanation":"Two hydrogens at $+1$ force sulphur to $-2$ in the neutral molecule.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-206","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Nitrogen in ammonia $\\mathrm{NH_3}$ is assigned the oxidation number","options":["$+3$","$-3$","$+5$","$0$"],"answer_index":1,"explanation":"Three hydrogens at $+1$ give nitrogen $-3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-207","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon in methane $\\mathrm{CH_4}$ carries the oxidation number","options":["$+4$","$-4$","$0$","$+2$"],"answer_index":1,"explanation":"Four hydrogens at $+1$ leave carbon at $-4$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-208","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In hydrogen peroxide $\\mathrm{H_2O_2}$ the oxidation number of each oxygen atom is","options":["$-2$","$-1$","$0$","$+1$"],"answer_index":1,"explanation":"Peroxidic oxygen is $-1$; two H at $+1$ and two O at $-1$ balance the molecule.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-209","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Sulphur in sulphuric acid $\\mathrm{H_2SO_4}$ has the oxidation number","options":["$+2$","$+4$","$+6$","$-2$"],"answer_index":2,"explanation":"$2(+1) + \\mathrm{S} + 4(-2) = 0$ gives S $= +6$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-210","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Chromium in potassium dichromate $\\mathrm{K_2Cr_2O_7}$ has the oxidation number","options":["$+3$","$+6$","$+7$","$+2$"],"answer_index":1,"explanation":"$2(+1) + 2\\mathrm{Cr} + 7(-2) = 0$ gives each Cr $= +6$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-211","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Manganese in potassium permanganate $\\mathrm{KMnO_4}$ is assigned","options":["$+2$","$+4$","$+6$","$+7$"],"answer_index":3,"explanation":"$+1 + \\mathrm{Mn} + 4(-2) = 0$ gives Mn $= +7$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-212","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Nitrogen in nitric acid $\\mathrm{HNO_3}$ has the oxidation number","options":["$-3$","$+3$","$+5$","$+1$"],"answer_index":2,"explanation":"$+1 + \\mathrm{N} + 3(-2) = 0$ gives N $= +5$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-213","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The average oxidation number of sulphur in sodium thiosulphate $\\mathrm{Na_2S_2O_3}$ is","options":["$+2$","$+4$","$+6$","$-2$"],"answer_index":0,"explanation":"$2(+1) + 2\\mathrm{S} + 3(-2) = 0$ gives $2\\mathrm{S} = +4$, so each S averages $+2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-214","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In magnetite $\\mathrm{Fe_3O_4}$ iron is present in two oxidation states. The average oxidation number of iron in $\\mathrm{Fe_3O_4}$ is","options":["$+2$","$+8/3$","$+3$","$+4$"],"answer_index":1,"explanation":"Four oxide ions contribute $-8$; three Fe atoms share $+8$, so the average is $+8/3$ (one Fe$^{2+}$ and two Fe$^{3+}$).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-215","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Oxidation, in electronic language, is the process in which a species","options":["gains electrons","loses electrons","gains protons","loses neutrons"],"answer_index":1,"explanation":"Loss of electrons raises the oxidation number and is oxidation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-216","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Reduction is identified as a","options":["gain of electrons","loss of electrons","gain of oxygen only","loss of hydrogen only"],"answer_index":0,"explanation":"Gain of electrons lowers the oxidation number and is reduction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-217","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An oxidising agent is the species that","options":["is itself oxidised","is itself reduced","does not change oxidation number","always contains hydrogen"],"answer_index":1,"explanation":"The oxidising agent accepts electrons and is reduced.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-218","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A reducing agent is the species that","options":["is itself reduced","is itself oxidised","only dilutes the mixture","must be a metal ion"],"answer_index":1,"explanation":"The reducing agent donates electrons and is oxidised.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-219","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"When magnesium ribbon burns, $2\\mathrm{Mg} + \\mathrm{O_2} \\rightarrow 2\\mathrm{MgO}$. The element that is oxidised is","options":["oxygen","magnesium","neither","both equally as oxidant"],"answer_index":1,"explanation":"Mg goes from 0 to $+2$ (loses electrons) and is oxidised; oxygen is reduced.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-220","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In $\\mathrm{Zn} + \\mathrm{Cu^{2+}} \\rightarrow \\mathrm{Zn^{2+}} + \\mathrm{Cu}$, the reducing agent is","options":["$\\mathrm{Cu^{2+}}$","Zn metal","the $\\mathrm{Zn^{2+}}$ ion formed","water"],"answer_index":1,"explanation":"Zinc metal loses electrons (0 to $+2$) and therefore reduces $\\mathrm{Cu^{2+}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-221","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A disproportionation reaction is one in which the same element is","options":["only oxidised","only reduced","simultaneously oxidised and reduced","left with an unchanged oxidation number"],"answer_index":2,"explanation":"Part of the element’s atoms rise in ON and part fall, as in $2\\mathrm{H_2O_2} \\rightarrow 2\\mathrm{H_2O} + \\mathrm{O_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-222","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The combination $\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$ is classified as redox because","options":["no oxidation number changes","hydrogen is oxidised (0 to $+1$) and chlorine is reduced (0 to $-1$)","it is only an acid–base reaction","both elements are oxidised"],"answer_index":1,"explanation":"H$_2$ loses electrons and Cl$_2$ gains them, so the combination is a redox process.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-223","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Which of the following laboratory changes is not a redox reaction?","options":["$2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O}$","$\\mathrm{Zn} + \\mathrm{H_2SO_4} \\rightarrow \\mathrm{ZnSO_4} + \\mathrm{H_2}$","$\\mathrm{HCl} + \\mathrm{NaOH} \\rightarrow \\mathrm{NaCl} + \\mathrm{H_2O}$","$\\mathrm{Fe_2O_3} + 3\\mathrm{CO} \\rightarrow 2\\mathrm{Fe} + 3\\mathrm{CO_2}$"],"answer_index":2,"explanation":"Acid–base neutralisation exchanges H$^+$ and OH$^-$ with no change in oxidation numbers.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-224","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In acid solution $\\mathrm{MnO_4^-}$ is reduced to $\\mathrm{Mn^{2+}}$. The number of electrons gained by one permanganate ion is","options":["2","3","5","7"],"answer_index":2,"explanation":"Mn goes from $+7$ to $+2$, a gain of five electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-225","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Dichromate $\\mathrm{Cr_2O_7^{2-}}$ is reduced to two $\\mathrm{Cr^{3+}}$ ions in acid. Electrons consumed per dichromate ion are","options":["3","4","6","8"],"answer_index":2,"explanation":"Two chromium atoms each fall from $+6$ to $+3$, a total of six electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"redox-balancing","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
